/* LudicrousSpeed — overlay bookmarklet (source of truth)
 *
 * Select text on any page, click the bookmarklet: an overlay that looks like
 * index.html opens on top of that page and the selection starts RSVP-ing.
 * The X in the top right corner (or Escape) closes it again.
 *
 * Tooling
 *   This file is written by hand; the code inside overlay-bookmarklet.html is
 *   generated by `npm run build` (build-overlay.mjs, dev dependency: terser).
 *   terser minifies this file (compress + mangle, comments stripped), then the
 *   result is percent-encoded into a `javascript:` URL and written into the
 *   href of `#install` in overlay-bookmarklet.html. Editing the HTML copy by
 *   hand is pointless — it gets overwritten. No runtime dependency: the
 *   bookmarklet is plain DOM + shadow DOM.
 *
 * Notes
 *   Everything lives in a (open) shadow root, so page CSS cannot reach in and
 *   the overlay CSS cannot leak out. `all: initial` on the host keeps inherited
 *   page styles out; rem units from index.html are converted to px so a page
 *   that changes its root font-size cannot rescale the overlay.
 *   The styles and markup mirror the reader in index.html — keep them in sync.
 *   The only intended visual differences: the theme button sits further left to
 *   make room for the close button in the corner.
 */

(() => {
  'use strict';

  if (window.__ludicrousSpeed) window.__ludicrousSpeed.close(); // replace a previous overlay

  const KEY = 'lso.'; // storage prefix, so nothing collides with the page or with index.html
  const SELECTED = readSelection();

  const ICONS = {
    play: '<svg viewBox="0 0 24 24"><path d="M8 4.5l11 7.5-11 7.5z"/></svg>',
    pause: '<svg viewBox="0 0 24 24"><path d="M6.5 4h4v16h-4zM13.5 4h4v16h-4z"/></svg>',
    replay: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 10a8 8 0 1 1 2 7"/><path d="M4 4v6h6"/></svg>',
    moon: '<svg viewBox="0 0 24 24"><path d="M20.5 13.2A8.6 8.6 0 1 1 10.8 3.5a6.9 6.9 0 0 0 9.7 9.7z"/></svg>',
    auto: '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.4"/><path d="M12 3.6a8.4 8.4 0 0 0 0 16.8z" fill="currentColor" stroke="none"/></svg>',
    sun: '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4.2"/><path d="M12 2.2v2.4M12 19.4v2.4M2.2 12h2.4M19.4 12h2.4M5 5l1.7 1.7M17.3 17.3 19 19M19 5l-1.7 1.7M6.7 17.3 5 19"/></svg>',
    close: '<svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18"/></svg>',
  };

  // index.html's stylesheet, scoped to .app / :host and with rem → px (1rem = 16px).
  const CSS = `
  *, *::before, *::after { box-sizing: border-box; }
  .app {
    color-scheme: light;
    --bg: #f4f3ef; --panel: #fff; --fg: #17181c; --muted: #6b6f76;
    --line: #e3e1da; --accent: #d94f3d; --accent-soft: rgba(217, 79, 61, .1);
    --guide: rgba(23, 24, 28, .18); --shadow: 0 12px 32px rgba(20, 20, 30, .07);
    --word-base: clamp(35.2px, 9vmin, 80px); --word-size: var(--word-base);
    position: fixed; inset: 0; z-index: 2147483647; margin: 0; overflow: auto; outline: none;
    background: var(--bg); color: var(--fg); display: flex; flex-direction: column; font-size: 16px;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    transition: background .2s, color .2s;
  }
  .app[data-theme="dark"] {
    color-scheme: dark;
    --bg: #101114; --panel: #17181d; --fg: #eceef1; --muted: #9aa0a8;
    --line: #272a31; --accent: #ff6b52; --accent-soft: rgba(255, 107, 82, .13);
    --guide: rgba(236, 238, 241, .18); --shadow: 0 12px 32px rgba(0, 0, 0, .35);
  }
  button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
  button:focus-visible, input:focus-visible, textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }

  .topbar {
    display: flex; align-items: center; justify-content: space-between;
    max-width: 960px; width: 100%; margin: 0 auto; padding: 16px 20px;
  }
  .brand { font-size: 16px; font-weight: 650; letter-spacing: -.01em; }
  .brand b { color: var(--accent); }
  .top-actions { display: flex; gap: 8px; align-items: center; }

  main { flex: 1; width: 100%; max-width: 960px; margin: 0 auto; padding: 0 20px 20px; display: flex; flex-direction: column; }
  .screen { flex: 1; display: flex; flex-direction: column; min-height: 0; }
  .hidden { display: none !important; }
  .muted { color: var(--muted); font-size: 14.4px; }
  .hintbar { margin: 14px 2px 0; }

  .panel {
    background: var(--panel); border: 1px solid var(--line); border-radius: 18px;
    padding: 18px; box-shadow: var(--shadow); display: flex; flex-direction: column; gap: 12px; transition: border-color .15s;
  }
  .panel.drag { border-color: var(--accent); background: var(--accent-soft); }
  .row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  textarea {
    width: 100%; min-height: 34vh; resize: vertical; padding: 14px; border-radius: 12px;
    border: 1px solid var(--line); background: var(--bg); color: var(--fg);
    font: inherit; line-height: 1.55; transition: border-color .15s;
  }
  textarea:focus { border-color: var(--accent); outline: none; }

  .btn { display: inline-flex; align-items: center; gap: 8px; border-radius: 10px; padding: 10px 16px; font-weight: 550; font-size: 15.2px; transition: transform .1s, background .15s, border-color .15s; }
  .btn:active { transform: translateY(1px); }
  .primary { background: var(--accent); color: #fff; }
  .primary:hover { filter: brightness(1.06); }
  .ghost { border: 1px solid var(--line); background: var(--panel); }
  .ghost:hover { border-color: var(--fg); }
  .warn { color: var(--accent); }

  .icon { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 12px; border: 1px solid var(--line); background: var(--panel); }
  .icon:hover { border-color: var(--fg); }
  .icon.auto { border-style: dashed; }
  .icon.close:hover { border-color: var(--accent); color: var(--accent); }
  .play-btn { width: 58px; height: 58px; border-radius: 50%; border: 0; background: var(--accent); color: #fff; }
  .play-btn:hover { filter: brightness(1.08); }
  .play-btn svg { width: 24px; height: 24px; stroke: none; fill: currentColor; }

  /* reader */
  .stage {
    position: relative; flex: 1; min-height: 42vh; overflow: hidden;
    touch-action: none; user-select: none; -webkit-user-select: none; cursor: pointer;
  }
  .hud {
    position: absolute; left: 50%; bottom: 10px; display: flex; align-items: baseline; gap: 8px;
    padding: 7px 14px; border-radius: 999px; background: var(--panel); border: 1px solid var(--line);
    box-shadow: var(--shadow); font-size: 13.6px; color: var(--muted); pointer-events: none;
    font-variant-numeric: tabular-nums; opacity: 0; transform: translate(-50%, 6px);
    transition: opacity .16s, transform .16s;
  }
  .hud b { color: var(--fg); font-weight: 650; }
  .stage.acting .hud { opacity: 1; transform: translate(-50%, 0); }
  .hint { display: none; margin: 10px 0 0; text-align: center; font-size: 12.48px; color: var(--muted); }
  .tick { position: absolute; left: 50%; width: 2px; margin-left: -1px; background: var(--guide); border-radius: 2px; height: max(18px, calc(var(--word-size) * 0.6)); }
  .tick.t { bottom: calc(50% + var(--word-size) * 0.8); }
  .tick.b { top: calc(50% + var(--word-size) * 0.8); }
  .word {
    position: absolute; left: 50%; top: 50%; white-space: nowrap;
    font-size: var(--word-size); font-weight: 600; letter-spacing: .01em;
    transform: translate(calc(-1 * var(--shift, 0px)), -50%);
  }
  .word #piv { color: var(--accent); }
  .meta { display: flex; justify-content: space-between; gap: 12px; font-size: 13.6px; color: var(--muted); padding: 4px 2px 8px; font-variant-numeric: tabular-nums; }
  .track { height: 16px; margin: 0 -6px; padding: 6px; cursor: pointer; }
  .track > div { height: 4px; border-radius: 4px; background: var(--line); overflow: hidden; }
  .track i { display: block; height: 100%; width: 0; background: var(--accent); border-radius: 4px; transition: width .15s linear; }
  .controls {
    display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 12px;
    background: var(--panel); border: 1px solid var(--line); border-radius: 16px; padding: 12px 14px; box-shadow: var(--shadow);
  }
  .speed { display: flex; align-items: center; gap: 8px; font-size: 13.6px; color: var(--muted); }
  .speed input {
    width: 110px; height: 28px; margin: 0; cursor: pointer; background: transparent;
    -webkit-appearance: none; appearance: none;
  }
  .speed input::-webkit-slider-runnable-track { height: 6px; border-radius: 3px; background: var(--line); }
  .speed input::-webkit-slider-thumb {
    -webkit-appearance: none; width: 22px; height: 22px; margin-top: -8px;
    border: 0; border-radius: 50%; background: var(--accent);
  }
  .speed input::-moz-range-track { height: 6px; border-radius: 3px; background: var(--line); }
  .speed input::-moz-range-thumb { width: 22px; height: 22px; border: 0; border-radius: 50%; background: var(--accent); }
  .speed output { min-width: 70.4px; color: var(--fg); font-variant-numeric: tabular-nums; font-size: 13.6px; }
  .spacer { margin-left: auto; }

  @media (max-width: 620px) {
    .topbar { padding: 10px 16px; }
    main { padding: 0 16px 10px; }
    .stage { min-height: 28vh; }
    .hint { font-size: 11.52px; margin-top: 8px; }
    .controls { gap: 8px 10px; justify-content: center; }
    .speed { flex: 1 1 100%; }
    .speed input { flex: 1; width: auto; min-width: 0; }
    .speed output { min-width: 67.2px; text-align: right; }
    .spacer { flex: 1 1 100%; justify-content: center; }
  }
  @media (pointer: coarse) {
    .speed input { width: 140px; height: 34px; }
    .speed input::-webkit-slider-thumb { width: 28px; height: 28px; margin-top: -11px; }
    .speed input::-moz-range-thumb { width: 28px; height: 28px; }
    .track { height: 28px; padding: 12px 6px; }
    .hint { display: block; }
  }
  @media (max-height: 560px) {
    .topbar { padding: 6px 16px; }
    .stage { min-height: 18vh; }
    .hint { display: none; }
  }
  `;

  const MARKUP = `
  <div class="app" id="app" tabindex="-1">
    <header class="topbar">
      <div class="brand">Ludicrous<b>Speed</b></div>
      <div class="top-actions">
        <button class="icon" id="themeBtn"></button>
        <button class="icon close" id="closeBtn" aria-label="Close" title="Close (Esc)"></button>
      </div>
    </header>
    <main>
      <section class="screen" id="setup">
        <div class="panel" id="panel">
          <div class="row">
            <label class="btn ghost">Choose file<input id="file" type="file" accept=".txt,.md,.markdown,.text,text/plain,text/markdown" hidden></label>
            <span class="muted">or drop a .txt / .md file here</span>
            <button class="btn ghost" id="sampleBtn">Sample text</button>
          </div>
          <textarea id="text" spellcheck="false" placeholder="Paste or type your text here…"></textarea>
          <div class="row">
            <span class="muted" id="stats">0 words · 0:00</span>
            <div class="spacer"></div>
            <button class="btn primary" id="startBtn">Start reading →</button>
          </div>
        </div>
        <p class="muted hintbar">Ctrl+Enter start · Space play/pause · ← → skip · ↑ ↓ speed · R restart · Esc close</p>
      </section>
      <section class="screen hidden" id="reader">
        <div class="stage" id="stage" title="Tap to play / pause — swipe ↑↓ size, ←→ speed">
          <div class="tick t"></div><div class="tick b"></div>
          <div class="word" id="word"><span id="pre"></span><span id="piv"></span><span id="post"></span></div>
          <div class="hud"><span id="hudLabel">Speed</span><b id="hudValue"></b></div>
        </div>
        <div class="meta"><span id="counter">1 / 1</span><span id="left">0:00 left</span></div>
        <div class="track" id="track" title="Click to seek"><div><i id="bar"></i></div></div>
        <div class="controls">
          <button class="icon" id="prevBtn" aria-label="Previous word" title="Previous (←)">«</button>
          <button class="play-btn" id="playBtn" aria-label="Play" title="Play / pause (Space)"></button>
          <button class="icon" id="nextBtn" aria-label="Next word" title="Next (→)">»</button>
          <div class="speed">
            <label for="wpm">Speed</label>
            <input id="wpm" type="range" min="100" max="1000" step="10">
            <output id="wpmOut" for="wpm">300 wpm</output>
          </div>
          <div class="speed">
            <label for="fs">Size</label>
            <input id="fs" type="range" min="0.7" max="1.6" step="0.05">
          </div>
          <button class="btn ghost spacer" id="editBtn">Edit text</button>
        </div>
        <p class="hint">Tap to play / pause · swipe ↑↓ size · ←→ speed</p>
      </section>
    </main>
  </div>`;

  /* --- shadow host ------------------------------------------------------ */

  const host = document.createElement('div');
  host.style.cssText = 'all: initial; display: block;';
  host.setAttribute('data-ludicrous-speed', '');
  host.setAttribute('role', 'dialog');
  host.setAttribute('aria-modal', 'true');
  host.setAttribute('aria-label', 'LudicrousSpeed reader');
  const root = host.attachShadow({ mode: 'open' });
  root.innerHTML = MARKUP;
  try { // constructable stylesheets still work on pages with a strict style-src CSP
    const sheet = new CSSStyleSheet();
    sheet.replaceSync(CSS);
    root.adoptedStyleSheets = [sheet];
  } catch {
    const style = document.createElement('style');
    style.textContent = CSS;
    root.prepend(style);
  }

  const $ = (id) => root.getElementById(id);
  const els = {
    app: $('app'), themeBtn: $('themeBtn'), closeBtn: $('closeBtn'), setup: $('setup'), reader: $('reader'), panel: $('panel'), file: $('file'),
    sampleBtn: $('sampleBtn'), text: $('text'), stats: $('stats'), startBtn: $('startBtn'),
    stage: $('stage'), word: $('word'), pre: $('pre'), piv: $('piv'), post: $('post'), counter: $('counter'), left: $('left'),
    hudLabel: $('hudLabel'), hudValue: $('hudValue'),
    track: $('track'), bar: $('bar'), prevBtn: $('prevBtn'), playBtn: $('playBtn'), nextBtn: $('nextBtn'),
    wpm: $('wpm'), wpmOut: $('wpmOut'), fs: $('fs'), editBtn: $('editBtn'),
  };

  /* --- settings --------------------------------------------------------- */

  const LS = {
    get(k, d) { try { const v = localStorage.getItem(KEY + k); return v === null ? d : JSON.parse(v); } catch { return d; } },
    set(k, v) { try { localStorage.setItem(KEY + k, JSON.stringify(v)); } catch {} },
  };
  const darkMedia = matchMedia('(prefers-color-scheme: dark)');
  // 'auto' follows the OS; an explicit light/dark choice is remembered and wins.
  function themeMode() { try { const m = JSON.parse(localStorage.getItem(KEY + 'theme')); return m === 'light' || m === 'dark' ? m : 'auto'; } catch { return 'auto'; } }
  function applyTheme(mode = themeMode()) {
    els.app.dataset.themeMode = mode;
    els.app.dataset.theme = mode === 'auto' ? (darkMedia.matches ? 'dark' : 'light') : mode;
  }

  const state = { words: [], i: 0, playing: false, done: false, wpm: LS.get('wpm', 300), fs: LS.get('fs', 1) };
  let timer = null, dragDepth = 0, statsTimer = null;

  const SAMPLE = `Speed reading with RSVP

Rapid Serial Visual Presentation is a reading technique that shows one word at a time in a fixed spot, so your eyes never have to move across a page. Without saccades, the small jumps your eyes make between words, you can read faster and with less effort. The highlighted letter marks the optimal recognition point, the spot where the eye naturally lands when it recognizes a word. Keep your gaze on that letter and let the words come to you.

Start slowly. Most people read between two hundred and three hundred words per minute, and pushing much faster than that right away feels like watching a movie on fast forward. Raise the speed in small steps and only move on when the text still feels comfortable.

Pause whenever you like. Skipping backwards is always allowed, and a paragraph break adds a small rest so the text keeps its rhythm. Reading is not a race, it is a conversation between you and the author.`;

  /* --- text model ------------------------------------------------------- */

  function readSelection() {
    let text = '';
    try { text = String(getSelection() || ''); } catch {}
    if (!text.trim()) {
      const el = document.activeElement;
      if (el && /^(INPUT|TEXTAREA)$/.test(el.tagName)) text = el.value.slice(el.selectionStart, el.selectionEnd);
    }
    return text.trim();
  }

  function tokenize(text) {
    const out = [];
    const re = /(\s*)(\S+)/g;
    let m;
    while ((m = re.exec(text))) out.push({ w: m[2], para: /\n\s*\n/.test(m[1]) });
    return out;
  }

  // Optimal recognition point: which character the eye should land on.
  function orpIndex(word) {
    const chars = Array.from(word);
    const leadMatch = word.match(/^[^\p{L}\p{N}]+/u);
    const lead = leadMatch ? Array.from(leadMatch[0]).length : 0;
    const core = Array.from(word.slice(lead)).filter((c) => /[\p{L}\p{N}]/u.test(c));
    const n = core.length || 1;
    const idx = n <= 1 ? 0 : n <= 5 ? 1 : n <= 9 ? 2 : n <= 13 ? 3 : 4;
    return Math.min(lead + idx, Math.max(0, chars.length - 1));
  }

  function delayFor(tok) {
    const n = Array.from(tok.w).length;
    const last = tok.w.replace(/["'”’)\]]+$/, '').slice(-1);
    let mult = 1;
    if (['.', '!', '?'].includes(last)) mult = 2;
    else if ([',', ';', ':'].includes(last)) mult = 1.5;
    if (tok.para) mult = Math.max(mult, 2.6);
    if (n > 8) mult *= 1 + Math.min(0.5, (n - 8) * 0.05);
    return Math.min(4000, (60000 / state.wpm) * mult);
  }

  /* --- rendering -------------------------------------------------------- */

  function render() {
    const tok = state.words[state.i];
    if (!tok) return;
    const chars = Array.from(tok.w);
    const p = orpIndex(tok.w);
    els.pre.textContent = chars.slice(0, p).join('');
    els.piv.textContent = chars[p] || '';
    els.post.textContent = chars.slice(p + 1).join('');
    const shrink = Math.max(0.3, Math.min(1, 14 / chars.length));
    els.word.style.fontSize = `calc(var(--word-size) * ${shrink.toFixed(3)})`;
    fitToStage();
    updateMeta();
  }

  function updateMeta() {
    const total = state.words.length || 1;
    els.counter.textContent = `${Math.min(state.i + 1, total)} / ${total}`;
    els.left.textContent = state.done ? 'finished' : `${fmt((total - state.i - 1) / state.wpm * 60)} left`;
    els.bar.style.width = `${((state.i + 1) / total) * 100}%`;
  }

  function wordMetrics() {
    const preW = els.pre.getBoundingClientRect().width;
    const pivW = els.piv.getBoundingClientRect().width;
    const wordW = els.word.getBoundingClientRect().width;
    const shift = preW + pivW / 2;
    return { wordW, shift, need: Math.max(shift, wordW - shift) };
  }

  function scaleFont(factor, min) {
    const fs = parseFloat(getComputedStyle(els.word).fontSize);
    els.word.style.fontSize = `${Math.max(min, fs * factor)}px`;
  }

  // Keep the pivot letter centred. If a word is too long for that, shrink it and,
  // as a last resort, centre the whole word so nothing gets cut off.
  function fitToStage() {
    const half = Math.max(1, els.word.parentElement.clientWidth / 2 - 8);
    let m = wordMetrics();
    if (m.need > half) { scaleFont(half / m.need, 12); m = wordMetrics(); }
    if (m.need > half) { scaleFont(Math.min(1, half / (m.wordW / 2)), 9); m = wordMetrics(); m.shift = m.wordW / 2; }
    els.word.style.setProperty('--shift', `${m.shift.toFixed(1)}px`);
  }

  function fmt(sec) {
    const t = Math.max(0, Math.round(sec));
    const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
    const pad = (n) => String(n).padStart(2, '0');
    return h ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`;
  }

  /* --- playback --------------------------------------------------------- */

  function schedule() {
    clearTimeout(timer);
    timer = setTimeout(() => advance(1), delayFor(state.words[state.i]));
  }

  function play() {
    if (!state.words.length) return;
    if (state.done) { state.i = 0; state.done = false; render(); }
    state.playing = true;
    syncPlayBtn();
    schedule();
  }

  function pause() {
    state.playing = false;
    clearTimeout(timer);
    timer = null;
    syncPlayBtn();
  }

  function advance(step) {
    if (!state.words.length) return;
    const next = state.i + step;
    if (next >= state.words.length) {
      state.i = state.words.length - 1;
      state.playing = false;
      state.done = true;
      clearTimeout(timer);
      syncPlayBtn();
      updateMeta();
      return;
    }
    state.i = Math.max(0, next);
    state.done = false;
    render();
    if (state.playing) schedule();
  }

  function seek(i) {
    state.i = Math.max(0, Math.min(state.words.length - 1, i));
    state.done = false;
    render();
    if (state.playing) schedule();
  }

  function syncPlayBtn() {
    const icon = state.playing ? ICONS.pause : state.done ? ICONS.replay : ICONS.play;
    els.playBtn.innerHTML = icon;
    els.playBtn.setAttribute('aria-label', state.playing ? 'Pause' : state.done ? 'Replay' : 'Play');
  }

  /* --- theme ------------------------------------------------------------ */

  const NEXT_THEME = { auto: 'light', light: 'dark', dark: 'auto' };

  function syncThemeBtn() {
    const mode = themeMode(), dark = els.app.dataset.theme === 'dark';
    els.themeBtn.innerHTML = mode === 'auto' ? ICONS.auto : dark ? ICONS.sun : ICONS.moon;
    els.themeBtn.classList.toggle('auto', mode === 'auto');
    const label = mode === 'auto' ? `Theme: auto (system is ${dark ? 'dark' : 'light'})` : `Theme: ${mode}`;
    els.themeBtn.setAttribute('aria-label', label);
    els.themeBtn.title = `${label} — click for ${NEXT_THEME[mode]}`;
  }

  function cycleTheme() {
    const next = NEXT_THEME[themeMode()];
    LS.set('theme', next);
    applyTheme(next);
    syncThemeBtn();
  }

  function onSchemeChange() {
    if (themeMode() !== 'auto') return;
    applyTheme('auto');
    syncThemeBtn();
  }

  /* --- setup screen ----------------------------------------------------- */

  function updateStats() {
    const text = els.text.value.trim();
    const n = tokenize(text).length;
    els.stats.textContent = `${n.toLocaleString()} words · ${fmt((n / state.wpm) * 60)}`;
    els.stats.classList.remove('warn');
  }

  function showScreen(reader) {
    els.setup.classList.toggle('hidden', reader);
    els.reader.classList.toggle('hidden', !reader);
  }

  function startReading() {
    const text = els.text.value.trim();
    if (!text) {
      els.stats.textContent = 'Add some text first…';
      els.stats.classList.add('warn');
      els.text.focus();
      return;
    }
    pause();
    state.words = tokenize(text);
    state.i = 0;
    state.done = false;
    showScreen(true);
    render();
    els.app.focus({ preventScroll: true });
    play();
  }

  function setWpm(v) {
    state.wpm = Math.round(Math.max(100, Math.min(1000, v)));
    els.wpm.value = state.wpm;
    els.wpmOut.textContent = `${state.wpm} wpm`;
    LS.set('wpm', state.wpm);
    if (!els.setup.classList.contains('hidden')) updateStats();
    updateMeta();
    if (state.playing) schedule();
  }

  function setFs(v) {
    state.fs = Math.max(0.7, Math.min(1.6, v));
    els.fs.value = state.fs;
    els.stage.style.setProperty('--word-size', `calc(var(--word-base) * ${state.fs})`);
    LS.set('fs', state.fs);
    render();
  }

  async function loadFile(file) {
    if (!file) return;
    try {
      els.text.value = (await file.text()).replace(/\r\n?/g, '\n');
      updateStats();
      els.text.focus();
    } catch {
      els.stats.textContent = `Could not read ${file.name}`;
      els.stats.classList.add('warn');
    }
  }

  /* --- stage gestures: drag to adjust, tap to play/pause --------------- */

  const DRAG_THRESHOLD = 10, WPM_PER_PX = 1.5, FS_PER_PX = 0.0025;
  let stageDrag = null, hudTimer = null;

  function showHud(label, value) {
    els.hudLabel.textContent = label;
    els.hudValue.textContent = value;
  }

  function onStageDown(e) {
    if (e.button || !e.isPrimary) return;
    clearTimeout(hudTimer);
    stageDrag = { id: e.pointerId, x: e.clientX, y: e.clientY, wpm: state.wpm, fs: state.fs, axis: null };
    try { els.stage.setPointerCapture(e.pointerId); } catch {}
    e.preventDefault();
  }

  function onStageMove(e) {
    const d = stageDrag;
    if (!d || e.pointerId !== d.id) return;
    const dx = e.clientX - d.x, dy = e.clientY - d.y;
    if (!d.axis) {
      if (Math.hypot(dx, dy) < DRAG_THRESHOLD) return;
      d.axis = Math.abs(dx) > Math.abs(dy) ? 'speed' : 'size';
      els.stage.classList.add('acting');
    }
    if (d.axis === 'speed') { setWpm(d.wpm + dx * WPM_PER_PX); showHud('Speed', `${state.wpm} wpm`); }
    else { setFs(d.fs - dy * FS_PER_PX); showHud('Size', `${Math.round(state.fs * 100)}%`); }
  }

  function onStageUp(e, tap) {
    const d = stageDrag;
    if (!d || e.pointerId !== d.id) return;
    stageDrag = null;
    if (els.stage.hasPointerCapture(d.id)) els.stage.releasePointerCapture(d.id);
    clearTimeout(hudTimer);
    hudTimer = setTimeout(() => els.stage.classList.remove('acting'), 700);
    if (tap && !d.axis) state.playing ? pause() : play();
  }

  /* --- keys ------------------------------------------------------------- */

  function onKey(e) {
    const target = e.composedPath()[0] || e.target;
    const tag = String(target.tagName || '').toLowerCase();
    const inReader = !els.reader.classList.contains('hidden');
    let handled = true;
    if (e.key === 'Escape') close();
    else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { if (!inReader) startReading(); }
    else if (tag === 'textarea' || tag === 'input') return; // let the setup screen type
    else if (!inReader) handled = false;
    else if (e.code === 'Space') state.playing ? pause() : play();
    else if (e.key === 'ArrowRight') advance(1);
    else if (e.key === 'ArrowLeft') advance(-1);
    else if (e.key === 'ArrowUp') setWpm(state.wpm + 20);
    else if (e.key === 'ArrowDown') setWpm(state.wpm - 20);
    else if (e.key === 'r' || e.key === 'R') { seek(0); if (!state.playing) play(); }
    else handled = false;
    if (!handled) return;
    e.preventDefault();
    e.stopPropagation();
  }

  function onResize() {
    if (!els.reader.classList.contains('hidden')) render();
  }

  /* --- open / close ----------------------------------------------------- */

  // Lock scrolling on both <html> and <body>: pages disagree about which one scrolls.
  const scrollRoots = [document.documentElement, document.body].filter(Boolean).map((el) => [el, el.style.overflow]);
  const prevFocus = document.activeElement;

  function close() {
    pause();
    clearTimeout(hudTimer);
    for (const [el, overflow] of scrollRoots) el.style.overflow = overflow;
    host.remove();
    removeEventListener('keydown', onKey, true);
    removeEventListener('resize', onResize);
    darkMedia.removeEventListener('change', onSchemeChange);
    if (window.__ludicrousSpeed && window.__ludicrousSpeed.close === close) delete window.__ludicrousSpeed;
    try { if (prevFocus && prevFocus.isConnected) prevFocus.focus({ preventScroll: true }); } catch {}
  }

  els.themeBtn.addEventListener('click', cycleTheme);
  els.closeBtn.addEventListener('click', close);
  els.startBtn.addEventListener('click', startReading);
  els.playBtn.addEventListener('click', () => (state.playing ? pause() : play()));
  els.prevBtn.addEventListener('click', () => advance(-1));
  els.nextBtn.addEventListener('click', () => advance(1));
  els.editBtn.addEventListener('click', () => { pause(); showScreen(false); els.text.focus(); });
  els.file.addEventListener('change', () => { loadFile(els.file.files[0]); els.file.value = ''; });
  els.text.addEventListener('input', () => { clearTimeout(statsTimer); statsTimer = setTimeout(updateStats, 150); });
  els.wpm.addEventListener('input', () => setWpm(+els.wpm.value));
  els.fs.addEventListener('input', () => setFs(+els.fs.value));
  els.sampleBtn.addEventListener('click', () => { els.text.value = SAMPLE; updateStats(); });

  els.stage.addEventListener('pointerdown', onStageDown);
  els.stage.addEventListener('pointermove', onStageMove);
  els.stage.addEventListener('pointerup', (e) => onStageUp(e, true));
  els.stage.addEventListener('pointercancel', (e) => onStageUp(e, false));

  els.track.addEventListener('click', (e) => {
    const r = els.track.getBoundingClientRect();
    seek(Math.floor(((e.clientX - r.left) / r.width) * state.words.length));
  });

  els.panel.addEventListener('dragenter', (e) => {
    if (!e.dataTransfer || !e.dataTransfer.types.includes('Files')) return;
    e.preventDefault();
    dragDepth++;
    els.panel.classList.add('drag');
  });
  els.panel.addEventListener('dragover', (e) => { if (e.dataTransfer && e.dataTransfer.types.includes('Files')) e.preventDefault(); });
  els.panel.addEventListener('dragleave', () => {
    if (--dragDepth <= 0) { dragDepth = 0; els.panel.classList.remove('drag'); }
  });
  els.panel.addEventListener('drop', (e) => {
    e.preventDefault();
    dragDepth = 0;
    els.panel.classList.remove('drag');
    loadFile(e.dataTransfer && e.dataTransfer.files[0]);
  });

  // Keep the host page out of the overlay: its clicks, keys, wheel and touch
  // handlers would otherwise fire on the retargeted events.
  for (const type of ['click', 'dblclick', 'keydown', 'keyup', 'keypress', 'mousedown', 'mouseup', 'pointerdown', 'pointerup', 'contextmenu', 'touchstart', 'touchmove', 'wheel'])
    host.addEventListener(type, (e) => e.stopPropagation());

  document.documentElement.append(host);

  for (const [el] of scrollRoots) el.style.overflow = 'hidden';
  addEventListener('keydown', onKey, true);
  addEventListener('resize', onResize);
  darkMedia.addEventListener('change', onSchemeChange);

  els.closeBtn.innerHTML = ICONS.close;
  applyTheme();
  syncThemeBtn();
  els.wpm.value = state.wpm;
  els.wpmOut.textContent = `${state.wpm} wpm`;
  els.fs.value = state.fs;
  els.stage.style.setProperty('--word-size', `calc(var(--word-base) * ${state.fs})`);
  syncPlayBtn();
  if (SELECTED) {
    els.text.value = SELECTED;
    updateStats();
    startReading();
  } else {
    updateStats();
    els.text.focus();
  }
  window.__ludicrousSpeed = { close };
})();
